import json
import pandas as pd
from scipy import stats

medals = pd.DataFrame(sql_results_0)
wdi = pd.DataFrame(sql_results_1)

def classify(ig):
    if ig is None:
        return None
    s = str(ig).strip()
    if s.startswith('High income'):
        return 'High'
    if s == 'Low income' or s == 'Lower middle income':
        return 'Low'
    return None

wdi['group'] = wdi['IncomeGroup'].apply(classify)
wdi = wdi[wdi['group'].notna()]

# Build mapping from country name variants to group
name_to_group = {}
for _, row in wdi.iterrows():
    g = row['group']
    for col in ['country', 'table_name', 'long_name']:
        v = row.get(col)
        if v:
            name_to_group[str(v).strip().lower()] = g

def match(name):
    if name is None:
        return None
    return name_to_group.get(str(name).strip().lower())

medals['group'] = medals['country'].apply(match)
medals = medals[medals['group'].notna()]

high = medals[medals['group']=='High']['medal_count'].astype(float).values
low = medals[medals['group']=='Low']['medal_count'].astype(float).values

t, p = stats.ttest_ind(high, low, equal_var=False)

print(json.dumps({'t': float(t), 'p': float(p)}))
